function extractInitialProps(html){
  const marker='window.__INITIAL_PROPS__ = JSON.parse("';
  const start=html.indexOf(marker);
  if(start===-1) return null;
  let i=start+marker.length, raw='';
  while(i<html.length){
    const ch=html[i];
    if(ch==='\\'){ raw+=ch+(html[i+1]||''); i+=2; continue; }
    if(ch==='"') break;
    raw+=ch; i++;
  }
  try{
    const jsonText=JSON.parse('"'+raw+'"');
    return JSON.parse(jsonText);
  }catch(e){ return null; }
}

function salaryText(s){
  if(!s || !s.range) return "";
  const {min,max}=s.range;
  if(!min && !max) return "";
  const cur=s.currency||"EUR";
  if(min && max) return `${min}-${max} ${cur}`;
  if(min) return `Más de ${min} ${cur}`;
  return `Hasta ${max} ${cur}`;
}

const out=[];
for(const item of $input.all()){
  const html=String(item.json.data||"");
  const state=extractInitialProps(html);
  const offers=(state && Array.isArray(state.offers)) ? state.offers : [];
  for(const j of offers){
    out.push({json:{
      source:"InfoJobs",
      id:j.code||"",
      title:j.title||"",
      company:j.companyName||"No indicada",
      location:[j.city, "España", j.teleworking].filter(Boolean).join(", ")||"No indicada",
      description:j.description||"",
      salary:salaryText(j.salary),
      published:j.publishedAt||"",
      url:j.link ? ("https:"+j.link) : ""
    }});
  }
}
return out;

