const p=$('Perfil profesional').first().json.profile;
const norm=s=>String(s||"").normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase().replace(/\b(\w+)\/[ao]\b/g,"$1");
const hard=(p.hard_exclusions||[]).map(norm);
const keys=(p.keywords||[]).map(norm);
const roles=[...(p.target_roles||[]),...(p.transition_roles||[])].map(norm);
const SPECIFIC_KEYWORDS=new Set([
  "franchise development","franchise expansion","franchisee recruitment",
  "business transfers","traspasos de negocio","commercial real estate","real estate comercial",
  "multi-unit management","multi-unit network","franchise agreements","international expansion",
  "horeca","desarrollo de franquicias","expansion de franquicias","captacion de franquiciados",
  "gestion multiunidad","expansion internacional","acuerdos de franquicia"
].map(norm));
const allowed=(p.locations_allowed||[]).map(norm);
const onsiteAllowed=(p.onsite_locations_allowed||[]).map(norm);
const hybridAllowed=(p.hybrid_locations_allowed||[]).map(norm);
const now=Date.now(), maxAge=(p.max_age_days||7)*86400000;

function dateMs(v){ if(!v)return null; if(typeof v==="number"){return v<1e12?v*1000:v;} const t=Date.parse(v); return Number.isNaN(t)?null:t; }
function isHybridText(t){return /\bhybrid\b|\bh[ií]brid[oa]s?\b/.test(t);}
function isRemoteText(t){return (/\bremote\b|\bremot[oa]s?\b|\bteletrabajo\b/.test(t)) && !isHybridText(t);}
function isPartTimeText(t){return /\bpart[\s-]?time\b|\btiempo parcial\b|\bmedia jornada\b|\bpor horas\b|\bfreelance\b|\bautonomo\b/.test(t);}

function isNonEuropeRemoteText(t){return /\blatinoamerica\b|\blatin america\b|\bestados unidos\b|\bunited states\b|\busa\b|\bcanada\b|\bmexico\b|\bargentina\b|\bcolombia\b|\bchile\b|\bperu\b|\bbrasil\b|\bbrazil\b|\basia\b|\bafrica\b|\baustralia\b|\bindia\b/.test(t);}
function isUnspecifiedSpainLocation(loc){
  const stripped = loc
    .replace(/\bespana\b/g, ' ')
    .replace(/\bspain\b/g, ' ')
    .replace(/\beuropa\b/g, ' ')
    .replace(/\beurope\b/g, ' ')
    .replace(/\bpresencial\b/g, ' ')
    .replace(/\bhibrid[oa]s?\b/g, ' ')
    .replace(/\bremot[oa]s?\b/g, ' ')
    .replace(/\bno indicada\b/g, ' ')
    .replace(/[,;.\-–—()]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return stripped.length === 0;
}
function isEuropeText(t){return /\beurope\b|\beuropa\b|\beuropean union\b|\bunion europea\b|\b(reino unido|united kingdom)\b|\buk\b|\bgermany\b|\balemania\b|\bfrance\b|\bfrancia\b|\bitaly\b|\bitalia\b|\bnetherlands\b|\bpaises bajos\b|\bholanda\b|\bportugal\b|\bbelgium\b|\bbelgica\b|\bpoland\b|\bpolonia\b|\bsweden\b|\bsuecia\b|\bdenmark\b|\bdinamarca\b|\bnorway\b|\bnoruega\b|\bireland\b|\birlanda\b|\baustria\b|\bswitzerland\b|\bsuiza\b|\bfinland\b|\bfinlandia\b|\bgreece\b|\bgrecia\b|\bczech\b|\brepublica checa\b|\bromania\b|\brumania\b|\bhungary\b|\bhungria\b|\bluxembourg\b|\bluxemburgo\b/.test(t);}

// Detects languages OTHER than English/Spanish explicitly required by the posting.
// Remote jobs based in Europe are only excluded on language grounds when they
// require a language other than English and/or Spanish; English/Spanish-only
// remote EU postings must never be excluded by this check.
const OTHER_LANGUAGE_PATTERNS=[
  [/\b(german|aleman)\b/,"german"],[/\b(french|frances)\b/,"french"],[/\b(italian|italiano)\b/,"italian"],
  [/\b(dutch|neerlandes|holandes)\b/,"dutch"],[/\b(portuguese|portugues)\b/,"portuguese"],
  [/\b(polish|polaco)\b/,"polish"],[/\b(swedish|sueco)\b/,"swedish"],[/\b(danish|danes)\b/,"danish"],
  [/\b(norwegian|noruego)\b/,"norwegian"],[/\b(finnish|finlandes)\b/,"finnish"],[/\b(greek|griego)\b/,"greek"],
  [/\b(czech|checo)\b/,"czech"],[/\b(romanian|rumano)\b/,"romanian"],[/\b(hungarian|hungaro)\b/,"hungarian"],
  [/\b(turkish|turco)\b/,"turkish"],[/\b(arabic|arabe)\b/,"arabic"],[/\b(mandarin|chinese|chino)\b/,"chinese"],
  [/\b(japanese|japones)\b/,"japanese"],[/\b(russian|ruso)\b/,"russian"]
];
const LANGUAGE_REQUIREMENT_MARKER=/\b(fluent|fluency|native|nativo|nativa|c1|c2|b2|proficient|proficiency|required|requerido|requerida|imprescindible|obligatorio|obligatoria|necesario|necesaria|se requiere|conocimientos de|dominio de|nivel alto de|advanced|working knowledge of)\b/;
function requiresOtherLanguage(t){
  for(const [re,name] of OTHER_LANGUAGE_PATTERNS){
    const m=t.match(re);
    if(!m) continue;
    const window=t.slice(Math.max(0,m.index-60), Math.min(t.length,m.index+60));
    if(LANGUAGE_REQUIREMENT_MARKER.test(window)) return name;
  }
  return null;
}

// Returns {type:"hourly"|"annual", value:number} or null if no salary is published.
// No published salary must NOT disqualify the listing (per profile instructions).
function parseSalarySignal(salaryStr, text){
  const s=String(salaryStr||"");
  const hourly=s.match(/([\d.,]+)\s*(?:€|eur)?\s*\/?\s*(?:hora|hour|h)\b/i) || text.match(/([\d.,]+)\s*(?:€|eur)\s*\/?\s*(?:hora|hour)\b/i);
  if(hourly){
    return {type:"hourly", value:Number(hourly[1].replace(/\./g,"").replace(",", "."))};
  }
  const annual=s.match(/(?:€|EUR)\s*([\d.,]+)/i) || s.match(/([\d.,]+)\s*(?:€|EUR)/i);
  if(annual){
    return {type:"annual", value:Number(annual[1].replace(/\./g,"").replace(",", "."))};
  }
  return null;
}

const out=[];
for(const it of $input.all()){
 const j=it.json, title=String(j.title||"").trim();
 if(!title) continue;
 const text=norm([title,j.company,j.location,j.description].join(" "));
 if(hard.some(x=>x&&text.includes(x))) continue;

 const titleRoles=roles.filter(x=>x&&norm(title).includes(x));
 const kwMatches=keys.filter(x=>x&&text.includes(x));
 const specificMatches=kwMatches.filter(x=>SPECIFIC_KEYWORDS.has(x));
 const genericMatches=kwMatches.filter(x=>!SPECIFIC_KEYWORDS.has(x));
 const matches=[...new Set(kwMatches.concat(titleRoles))];
 // Título coincide con un rol objetivo, o keyword específica -> 1 señal alcanza.
 // Solo keywords genéricas (amplias, poco específicas) -> hacen falta 2 para corroborar.
 const strongSignal = titleRoles.length>0 || specificMatches.length>0;
 if(!strongSignal && genericMatches.length < (p.minimum_keyword_matches||2)) continue;

 const loc=norm(j.location);
 const hybrid=isHybridText(text);
 const remote=isRemoteText(text);
 const work_mode = remote ? "remote" : (hybrid ? "hybrid" : "onsite");

 if(work_mode==="remote" && !p.remote_allowed) continue;
 if(work_mode==="hybrid" && !p.hybrid_allowed) continue;
 if(work_mode==="onsite" && !p.onsite_allowed) continue;

 // Onsite: only Málaga. Hybrid: Málaga, Madrid or Andalucía (e.g. Sevilla). Remote: anywhere in Europe.
 // A location field that only says "España"/blank (no city) can't be confirmed as ineligible,
 // so it gets the benefit of the doubt; a location that names a specific city still has to match.
 const locSpecified = !isUnspecifiedSpainLocation(loc);
 if(work_mode==="onsite" && locSpecified && !onsiteAllowed.some(x=>x&&loc.includes(x))) continue;
 if(work_mode==="hybrid" && locSpecified && !hybridAllowed.some(x=>x&&loc.includes(x))) continue;
 if(work_mode==="remote"){
   const explicitlyNonEurope = isNonEuropeRemoteText(text) && !isEuropeText(text) && !allowed.some(x=>x&&loc.includes(x));
   if(explicitlyNonEurope) continue;
 }

 if(remote && isEuropeText(text) && requiresOtherLanguage(text)) continue;

 const dt=dateMs(j.published);
 if(dt && now-dt>maxAge) continue;

 const salarySignal=parseSalarySignal(j.salary, text);
 if(salarySignal){
   if(salarySignal.type==="hourly"){
     if(p.minimum_hourly_rate && salarySignal.value < p.minimum_hourly_rate) continue;
   } else {
     const partTime=isPartTimeText(text);
     const threshold=partTime ? p.minimum_salary_part_time : p.minimum_salary_full_time;
     if(threshold && salarySignal.value < threshold) continue;
   }
 }
 // No salary published -> do not discard, keep the listing.

 const canonical=String(j.url||"").trim();
 const id=j.id || canonical || `${j.source}|${j.company}|${title}|${j.location}`;
 out.push({json:{
   ...j,id,title,company:j.company||"No indicada",location:j.location||"No indicada",
   salary:j.salary||"No indicado",published:j.published||"No indicada",
   description:String(j.description||"").replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim(),
   url:canonical,matches,match_count:matches.length,remote,hybrid,work_mode
 }});
}
return out.sort((a,b)=>b.json.match_count-a.json.match_count);

