function extractRaw(json){
  if (typeof json.output === "string") return json.output;
  if (json.choices?.[0]?.message?.content) return json.choices[0].message.content;
  return "";
}

function stripFence(raw){
  const m = String(raw).match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  return m ? m[1] : raw;
}

function parseRating(raw){
  const cleaned = stripFence(raw).trim();
  try{
    return typeof cleaned === "string" ? JSON.parse(cleaned) : cleaned;
  }catch(e){
    return {match:0, apply:false, reason:"OpenRouter no devolvió JSON válido"};
  }
}

const items = $input.all();
const baseItems = $('Solo ofertas nuevas').all();

return items.map((item, i) => {
  const raw = extractRaw(item.json);
  const s = parseRating(raw);
  const base = (baseItems[i] && baseItems[i].json) || {};
  return {json:{
    ...base,
    score:Number(s.match||0),
    role_fit:Number(s.role_fit||0),
    location_fit:Number(s.location_fit||0),
    salary_fit:Number(s.salary_fit||0),
    seniority_fit:Number(s.seniority_fit||0),
    remote_fit:Number(s.remote_fit||0),
    apply:Boolean(s.apply),
    reason:String(s.reason||"")
  }};
});

const order={remote:0,hybrid:1,onsite:2};
const items=$input.all();
items.sort((a,b)=>{
  const pa=order[a.json.work_mode]??3, pb=order[b.json.work_mode]??3;
  if(pa!==pb) return pa-pb;
  return (b.json.score||0)-(a.json.score||0);
});
return items;

